/// <summary>
/// Human-readable label showing the effect of the toggle: e.g.
/// "10× turn budget (200 → 2000)". Always returns the label text;
/// visibility is controlled by <see cref="AreTaskTogglesVisible"/>.
/// </summary>

[Fact]
public void TurnBudgetLabel_shows_calculated_numbers()
{
    var viewModel = new MainWindowViewModel();

    // No task selected, no root path — label always returns its text.
    Assert.Equal("10× turn budget (200 → 2000)", viewModel.TurnBudgetLabel);

    // Toggles should be hidden with no selection.
    Assert.False(viewModel.AreTaskTogglesVisible);

    // CanToggleTurnBudget should be false with no selection.
    Assert.False(viewModel.CanToggleTurnBudget);
}

